/bin/bash -lc "python3 - <<'PY'
import urllib.request
base='https://raw.githubusercontent.com/NVIDIA/cuda-samples/db3eea23946bca2e90a75eca2b5b3e07158a9e11/'
files={'Samples/5_Domain_Specific/MonteCarloMultiGPU/MonteCarloMultiGPU.cpp':[(147,194),(269,327),(426,442),(479,488)],'Samples/5_Domain_Specific/MonteCarloMultiGPU/MonteCarlo_kernel.cu':[(125,179),(190,223)],'Samples/5_Domain_Specific/MonteCarloMultiGPU/CMakeLists.txt':[(1,100)]}
for name,ranges in files.items():
 print(name)
 try:
  lines=urllib.request.urlopen(base+name,timeout=20).read().decode().splitlines()
  for lo,hi in ranges:
   for i in range(lo-1,min(hi,len(lines))): print(f'{i+1}: {lines[i]}')
 except Exception as e: print(type(e).__name__,str(e))
PY"

